#!/usr/bin/env bash
#
# TRU_ADDR_DIAL_01_SOURCE_PATCH.sh
#
# SOURCE ONLY. Patches exactly one file:   src/message_handler.cpp
# Does NOT compile, does NOT touch the chain, wallet, config or binary.
#
# Drop this in a repo root and run it there. Works in both trees:
#     cd ~/NEW_TRU            && bash ./TRU_ADDR_DIAL_01_SOURCE_PATCH.sh
#     cd ~/TRU-release-clean  && bash ./TRU_ADDR_DIAL_01_SOURCE_PATCH.sh
#
# It detects which tree it is in from the file's own hash and applies the
# matching variant. The two trees differ only in stripped comment labels.
#
# THE BUG (ADDR-DIAL-01)
#   The ADDR handler runs on the PeerConnection reader thread
#   (peer_connection.cpp:208 readThread_ -> readLoop -> handleMessage:657)
#   and dialled peers synchronously from there, counting only SUCCESSFUL
#   dials against its cap:
#
#       if (newConnectionCount < MAX_NEW_CONNECTIONS)
#           if (node->connectToPeer(ip, port))   // 5s default timeout
#               newConnectionCount++;            // only on success
#
#   Unreachable addresses cost 5s each and never consumed the budget, so a
#   50-address ADDR could hold the reader for over four minutes. While it is
#   held the socket is not read: GET_HEIGHT goes unanswered and block
#   exchange stalls although the connection still looks open. The cap was
#   loosest exactly when the network was worst.
#
#   The three counters were function-static, i.e. one copy shared by every
#   reader thread with no synchronisation - a data race, and the "per
#   message" comment was untrue.
#
# THE FIX
#   A mutex-guarded governor plus a genuine per-message local:
#     - counts ATTEMPTS, not successes
#     - max 2 dials per ADDR message
#     - max 6 dials per minute across ALL reader threads
#     - failed endpoint suppressed for 900s
#     - 1s dial timeout instead of the 5s default
#     - cooldown map hard-capped at 512 entries
#   Worst-case reader stall: 2s, down from 250s.
#
# Re-running is safe: an already-patched tree is detected and left alone.
#
set -Eeuo pipefail

REPO="${TRU_REPO:-$PWD}"
TARGET="${REPO}/src/message_handler.cpp"
STAMP="$(date +%Y%m%d-%H%M%S)"
SCRATCH="$(mktemp -d)"
BACKUP="${REPO}/src/message_handler.cpp.pre-addr-dial-01.${STAMP}.bak"

EMBEDDED_BUNDLE_SHA256="d28021b865395590962965bcf003974845dfee349bf08323c9e097b5a6cdcf00"
PRE_NEW_TRU_SHA256="4c2dde94058f61ff8efc66a8b40487b0b254756c257bcb01d7f0005bf20120b8"
POST_NEW_TRU_SHA256="af53d0a68d4fbf902c2114cf4b5445c4802a241adcd7c2394cfd15671ad0664b"
PRE_CLEAN_SHA256="44129904d181c3cb2d0e329bd4298add9c3fbd71558241ee8fc3f29da62257e6"
POST_CLEAN_SHA256="74fa244e50208d510bacd56a5ecb8c77df082d07674be1b43cfa1d918b70a424"

say() { printf '%s\n' "$*"; }
sha_of() { sha256sum "$1" | awk '{print $1}'; }
die() { printf '\nFAIL: %s\n' "$*" >&2; exit 1; }
cleanup() { rm -rf "$SCRATCH"; }
trap cleanup EXIT

say "=============================================================="
say " TRU_ADDR_DIAL_01   source patch (no build)"
say " repo: ${REPO}"
say "=============================================================="

say ""
say "[0] PACKAGE SELF-CHECK"
command -v python3 >/dev/null 2>&1 || die "python3 required"
sed -n "/^#__BEGIN_BUNDLE_B64__$/,/^#__END_BUNDLE_B64__$/p" "$0" \
    | sed -e '1d' -e '$d' -e 's/^#//' | base64 -d > "${SCRATCH}/bundle.bin"
[ "$(sha_of "${SCRATCH}/bundle.bin")" = "$EMBEDDED_BUNDLE_SHA256" ] \
    || die "embedded bundle sha mismatch"
say "    EMBEDDED_BUNDLE_PIN=PASS"

say ""
say "[1] LOCATE TARGET"
[ -f "$TARGET" ] || die "no src/message_handler.cpp under ${REPO}
Run this from a TRU repo root, or set TRU_REPO=/path/to/repo."
[ -L "$TARGET" ] && die "src/message_handler.cpp is a symlink; refusing"
[ -w "$TARGET" ] || die "src/message_handler.cpp is not writable by $(id -un).
If it is root-owned:  sudo chown -R \$(id -un):\$(id -gn) ${REPO}"
say "    target: src/message_handler.cpp"

say ""
say "[2] DETECT TREE"
actual="$(sha_of "$TARGET")"
if   [ "$actual" = "$POST_NEW_TRU_SHA256" ] || [ "$actual" = "$POST_CLEAN_SHA256" ]; then
    say ""
    say "ALREADY PATCHED - this tree is already at the ADDR-DIAL-01 post hash."
    say "Nothing to do. Exiting cleanly."
    exit 0
elif [ "$actual" = "$PRE_NEW_TRU_SHA256" ]; then
    VARIANT="new_tru"; EXPECT_POST="$POST_NEW_TRU_SHA256"
    say "    VARIANT=NEW_TRU (patch labels present)"
elif [ "$actual" = "$PRE_CLEAN_SHA256" ]; then
    VARIANT="clean";   EXPECT_POST="$POST_CLEAN_SHA256"
    say "    VARIANT=RELEASE_CLEAN (labels stripped)"
else
    die "src/message_handler.cpp matches neither supported tree.
  found      ${actual}
  NEW_TRU    ${PRE_NEW_TRU_SHA256}
  clean      ${PRE_CLEAN_SHA256}
DO NOT edit a pin to make this pass. Send me your current file instead."
fi
say "    PREHASH_PIN=PASS"

say ""
say "[3] BACKUP"
cp -p "$TARGET" "$BACKUP"
say "    ${BACKUP}"

say ""
say "[4] BUILD AND CHECK CANDIDATE"
python3 - "$SCRATCH" "$VARIANT" << 'INNER_PY'
import pathlib, sys
scratch, variant = pathlib.Path(sys.argv[1]), sys.argv[2]
raw = (scratch / "bundle.bin").read_text(encoding="utf-8")
parts = {}
for chunk in raw.split("====VARIANT:")[1:]:
    name, body = chunk.split("====\n", 1)
    parts[name] = body
if variant not in parts:
    sys.stderr.write("bundle lacks variant %s\n" % variant); raise SystemExit(1)
body = parts[variant]
live = "\n".join(l for l in body.splitlines() if not l.strip().startswith("//"))
for gone in ("static int newConnectionCount", "static time_t lastReset",
             "static const int MAX_NEW_CONNECTIONS"):
    if gone in live:
        sys.stderr.write("candidate still has shared static: %s\n" % gone)
        raise SystemExit(1)
for need in ("dialsThisMessage", "tryReserve", "penalize",
             "ADDR_DIAL_TIMEOUT_SECONDS", "addrDialGovernor"):
    if need not in live:
        sys.stderr.write("candidate missing %s\n" % need); raise SystemExit(1)
if body.count("{") != body.count("}"):
    sys.stderr.write("candidate braces unbalanced\n"); raise SystemExit(1)
(scratch / "message_handler.cpp").write_text(body, encoding="utf-8")
print("    SHARED_STATICS_REMOVED=PASS")
print("    GOVERNOR_PRESENT=PASS")
print("    BRACES_BALANCED=PASS")
INNER_PY
[ "$(sha_of "${SCRATCH}/message_handler.cpp")" = "$EXPECT_POST" ] \
    || die "candidate does not match the derived post pin for ${VARIANT}"
say "    CANDIDATE_PIN=PASS"

say ""
say "[5] INSTALL"
cp "${SCRATCH}/message_handler.cpp" "$TARGET"
post="$(sha_of "$TARGET")"
if [ "$post" != "$EXPECT_POST" ]; then
    cp -p "$BACKUP" "$TARGET"
    die "posthash mismatch after write; original restored from backup"
fi
say "    INSTALLED_PIN=PASS"

# Optional local syntax sanity. Missing project headers are expected here;
# a brace or paren error is not.
if command -v g++ >/dev/null 2>&1; then
    if g++ -fsyntax-only -std=c++17 "$TARGET" 2>&1 \
         | grep -qE "expected .\}.|unbalanced|expected .;. before|stray"; then
        cp -p "$BACKUP" "$TARGET"
        die "local syntax check found a structural error; original restored"
    fi
    say "    LOCAL_SYNTAX_SANITY=PASS (header errors ignored)"
fi

say ""
say "=============================================================="
say "TRU_ADDR_DIAL_01=PATCHED  variant=${VARIANT}"
say ""
say "PRE  ${actual}"
say "POST ${post}"
say ""
say "WORST_CASE_READER_STALL=2s  (was 250s)"
say "SHARED_STATIC_RACE=REMOVED"
say "SOURCE_ONLY=YES  (nothing was compiled)"
say ""
if [ -f "${REPO}/${TRU_BUILD_DIR:-build-native}/CMakeCache.txt" ]; then
    say "This tree has a build directory. To make it live:"
    say "  stop node, miners and Agent, then"
    say "  cmake --build ${TRU_BUILD_DIR:-build-native} --target tru_advanced -j\$(nproc)"
    say "  restart the node"
else
    say "No build directory here - this looks like a staging/publish tree."
    say "Commit and push, or build it wherever it is deployed."
fi
say ""
say "Revert:"
say "  cp -p ${BACKUP} ${TARGET}"
say "=============================================================="
exit 0

